using System.Collections.Generic;public class PhoneDirectory{Queue<int>q=new();bool[]used;public PhoneDirectory(int n){used=new bool[n];for(int i=0;i<n;i++)q.Enqueue(i);}public int Get(){if(q.Count==0)return-1;int x=q.Dequeue();used[x]=true;return x;}public bool Check(int n)=>n>=0&&n<used.Length&&!used[n];public void Release(int n){if(n>=0&&n<used.Length&&used[n]){used[n]=false;q.Enqueue(n);}}}
